data class Money(val cents: Long) : Comparable<Money> {
    override fun compareTo(other: Money): Int = cents.compareTo(other.cents)  // <, <=, >, >= follow
    operator fun plus(other: Money) = Money(cents + other.cents)              // m1 + m2
}

data class Version(val major: Int, val minor: Int) : Comparable<Version> {
    override fun compareTo(other: Version) =
        compareValuesBy(this, other, Version::major, Version::minor)          // one body for a version family
}
